css:
.agritech-innovation-container {
    padding: 28px;
    background: linear-gradient(135deg, #0d2b1e 0%, #1a3a2f 50%, #0f172a 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e2e8f0;
}

.agritech-innovation-header {
    background: rgba(255, 255, 255, 0.08);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 255, 0.15);
    border-radius: 20px;
    padding: 32px;
    text-align: center;
    margin-bottom: 28px;
    border-top: 3px solid #52b788;
}

.agritech-innovation-header h1 {
    margin: 0 0 8px 0;
    font-size: 1.6rem;
    font-weight: 700;
    background: linear-gradient(135deg, #52b788, #a78bfa);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.agritech-innovation-subtitle {
    margin: 0;
    opacity: 0.9;
    font-size: 0.95rem;
    color: #94a3b8;
}

.agritech-innovation-period-bar {
    background: rgba(255, 255, 255, 0.07);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 12px;
    padding: 16px 24px;
    margin-bottom: 24px;
    font-weight: 600;
    color: #e2e8f0;
    display: flex;
    align-items: center;
    gap: 8px;
}

.agritech-innovation-round-title {
    margin-left: auto;
    color: #52b788;
    font-weight: 500;
    font-size: 0.9rem;
}

.agritech-innovation-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 20px;
    margin-bottom: 28px;
}

.agritech-innovation-kpi-card {
    background: rgba(255, 255, 255, 0.07);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 16px;
    padding: 24px;
    position: relative;
    overflow: hidden;
    transition: background 0.25s ease, transform 0.2s ease;
}

.agritech-innovation-kpi-card:hover {
    background: rgba(255, 255, 255, 0.12);
    transform: translateY(-4px);
}

.agritech-innovation-kpi-card::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, #52b788, #a78bfa);
}

.agritech-innovation-kpi-label {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #94a3b8;
    margin-bottom: 8px;
    font-weight: 600;
}

.agritech-innovation-kpi-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #ffffff;
    line-height: 1.2;
}

.agritech-innovation-kpi-bar {
    height: 6px;
    background: rgba(255, 255, 255, 0.1);
    border-radius: 3px;
    margin-top: 12px;
    overflow: hidden;
}

.agritech-innovation-kpi-fill {
    height: 100%;
    background: linear-gradient(90deg, #ef4444, #f59e0b);
    transition: width 0.3s ease;
}

.agritech-innovation-alert {
    background: rgba(239, 68, 68, 0.15);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(239, 68, 68, 0.3);
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 24px;
}

.agritech-innovation-alert strong {
    color: #fca5a5;
    display: block;
    margin-bottom: 8px;
    font-size: 0.9rem;
}

.agritech-innovation-alert p {
    margin: 0;
    color: #e2e8f0;
    font-size: 0.9rem;
    line-height: 1.5;
}

.agritech-innovation-briefing {
    background: rgba(255, 255, 255, 0.07);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 24px;
}

.agritech-innovation-briefing h3 {
    margin: 0 0 12px 0;
    color: #52b788;
    font-size: 1.1rem;
    font-weight: 600;
}

.agritech-innovation-briefing p {
    margin: 0;
    line-height: 1.6;
    color: #cbd5e1;
}

.agritech-innovation-projects {
    background: rgba(255, 255, 255, 0.07);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 24px;
}

.agritech-innovation-projects h3 {
    margin: 0 0 16px 0;
    color: #a78bfa;
    font-size: 1.1rem;
    font-weight: 600;
}

.agritech-innovation-project-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 16px;
}

.agritech-innovation-project-card {
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 16px;
}

.agritech-innovation-project-name {
    font-weight: 600;
    color: #52b788;
    margin-bottom: 8px;
    font-size: 1rem;
}

.agritech-innovation-project-stats {
    font-size: 0.85rem;
    color: #94a3b8;
    line-height: 1.5;
}

.agritech-innovation-decision-panel {
    background: rgba(255, 255, 255, 0.07);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 24px;
}

.agritech-innovation-decision-panel h3 {
    margin: 0 0 20px 0;
    color: #e2e8f0;
    font-size: 1.1rem;
    font-weight: 600;
    padding-bottom: 12px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.agritech-innovation-form-group {
    margin-bottom: 20px;
}

.agritech-innovation-form-group label {
    display: block;
    font-weight: 600;
    color: #e2e8f0;
    margin-bottom: 8px;
    font-size: 0.9rem;
}

.agritech-innovation-form-group select,
.agritech-innovation-form-group input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 8px;
    color: #ffffff;
    font-size: 0.95rem;
    font-family: inherit;
}

.agritech-innovation-form-group select option {
    background: #1a3a2f;
    color: #ffffff;
}

.agritech-innovation-form-group select:focus,
.agritech-innovation-form-group input:focus {
    outline: none;
    border-color: #52b788;
    box-shadow: 0 0 0 3px rgba(82, 183, 136, 0.2);
}

.agritech-innovation-hint {
    font-size: 0.85rem;
    color: #94a3b8;
    margin-top: 6px;
    font-style: italic;
}

.agritech-innovation-actions {
    display: flex;
    gap: 12px;
    margin-bottom: 28px;
}

.agritech-innovation-btn {
    padding: 12px 24px;
    border-radius: 8px;
    font-weight: 600;
    font-size: 0.95rem;
    cursor: pointer;
    transition: all 0.2s ease;
    border: none;
    font-family: inherit;
}

.agritech-innovation-btn-primary {
    background: linear-gradient(135deg, #52b788, #3d8b6a);
    color: white;
}

.agritech-innovation-btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(82, 183, 136, 0.4);
}

.agritech-innovation-btn-secondary {
    background: rgba(255, 255, 255, 0.1);
    color: #e2e8f0;
    border: 1px solid rgba(255, 255, 255, 0.2);
}

.agritech-innovation-btn-secondary:hover {
    background: rgba(255, 255, 255, 0.15);
}

.agritech-innovation-chart-container {
    background: rgba(255, 255, 255, 0.07);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 24px;
    height: 320px;
    position: relative;
}

.agritech-innovation-history {
    background: rgba(255, 255, 255, 0.07);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 16px;
    padding: 24px;
    overflow-x: auto;
}

.agritech-innovation-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
    color: #e2e8f0;
}

.agritech-innovation-table th,
.agritech-innovation-table td {
    padding: 12px;
    text-align: left;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.agritech-innovation-table th {
    font-weight: 600;
    color: #52b788;
    background: rgba(82, 183, 136, 0.1);
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 0.05em;
}

.agritech-innovation-table tr:hover {
    background: rgba(255, 255, 255, 0.05);
}

@media (max-width: 768px) {
    .agritech-innovation-container {
        padding: 16px;
    }

    .agritech-innovation-kpi-grid {
        grid-template-columns: 1fr;
    }

    .agritech-innovation-header {
        padding: 20px;
    }

    .agritech-innovation-actions {
        flex-direction: column;
    }

    .agritech-innovation-btn {
        width: 100%;
    }
}

