        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var period = window.mySimulation.state.currentPeriod || 1;

            if (period === 1) {
                var terraEl = document.getElementById('terraStrategy');
                var pestEl = document.getElementById('pestStrategy');
                var yieldEl = document.getElementById('yieldStrategy');

                if (terraEl) decisions.terraStrategy = terraEl.value;
                if (pestEl) decisions.pestStrategy = pestEl.value;
                if (yieldEl) decisions.yieldStrategy = yieldEl.value;
            } else if (period === 2) {
                var upfrontEl = document.getElementById('licenseUpfront');
                var royaltyEl = document.getElementById('licenseRoyalty');
                var accessEl = document.getElementById('futureAccess');
                var exclEl = document.getElementById('exclusivity');

                if (upfrontEl) decisions.licenseUpfront = parseInt(upfrontEl.value) || 30;
                if (royaltyEl) decisions.licenseRoyalty = parseInt(royaltyEl.value) || 17;
                if (accessEl) decisions.futureAccess = accessEl.value;
                if (exclEl) decisions.exclusivity = exclEl.value;

                if (decisions.licenseRoyalty > 20) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('high_royalty_warning'), 'warning');
                }
            } else if (period === 3) {
                var fundEl = document.getElementById('zamoranoFunding');
                var ipEl = document.getElementById('ipOwnership');
                var commEl = document.getElementById('commercialRights');
                var pubEl = document.getElementById('pubRights');

                if (fundEl) decisions.zamoranoFunding = parseInt(fundEl.value) || 200;
                if (ipEl) decisions.ipOwnership = ipEl.value;
                if (commEl) decisions.commercialRights = commEl.value;
                if (pubEl) decisions.pubRights = pubEl.value;
            } else {
                var terra2El = document.getElementById('terra2Invest');
                var blockEl = document.getElementById('blockchainInvest');
                var revEl = document.getElementById('revenueTarget');

                if (terra2El) decisions.terra2Invest = parseInt(terra2El.value) || 0;
                if (blockEl) decisions.blockchainInvest = parseInt(blockEl.value) || 0;
                if (revEl) decisions.revenueTarget = parseFloat(revEl.value) || 6.5;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var riskChange = 0;
            var revenueChange = 0;

            if (period === 1) {
                ds.terraStrategy = d.terraStrategy || 'internal';
                ds.pestStrategy = d.pestStrategy || 'internal';
                ds.yieldStrategy = d.yieldStrategy || 'internal';

                if (ds.terraStrategy === 'internal') {
                    riskChange += 20;
                } else if (ds.terraStrategy === 'license') {
                    riskChange -= 50;
                    revenueChange -= 0.3;
                } else if (ds.terraStrategy === 'designaround') {
                    ds.budget -= 100000;
                    riskChange -= 30;
                } else {
                    ds.activeProjects -= 1;
                    ds.budget += 200000;
                }

                if (ds.pestStrategy === 'university') {
                    ds.budget -= 50000;
                } else if (ds.pestStrategy === 'abandon') {
                    ds.activeProjects -= 1;
                    ds.budget += 250000;
                }

                if (ds.yieldStrategy === 'abandon') {
                    ds.activeProjects -= 1;
                    ds.budget += 150000;
                }
            } else if (period === 2) {
                ds.licenseUpfront = d.licenseUpfront || 30;
                ds.licenseRoyalty = d.licenseRoyalty || 17;
                ds.futureAccess = d.futureAccess || 'yes';
                ds.exclusivity = d.exclusivity || 'yes';

                ds.budget -= ds.licenseUpfront * 1000;
                riskChange -= 20;

                if (ds.exclusivity === 'yes') {
                    revenueChange += 0.5;
                }
                if (ds.futureAccess === 'yes') {
                    revenueChange += 0.2;
                }
            } else if (period === 3) {
                ds.zamoranoFunding = d.zamoranoFunding || 200;
                ds.ipShared = (d.ipOwnership === 'coowner');
                ds.commercialRights = d.commercialRights || 'exclusive5';

                ds.budget -= (ds.zamoranoFunding * 2 - 200000);

                if (ds.zamoranoFunding < 200) {
                    riskChange += 10;
                } else {
                    revenueChange += 0.4;
                }
            } else {
                ds.terra2Invest = d.terra2Invest || 0;
                ds.blockchainInvest = d.blockchainInvest || 0;

                ds.budget -= ds.terra2Invest;
                ds.budget -= ds.blockchainInvest;

                if (ds.terra2Invest > 0) {
                    revenueChange += 1.0;
                }
                if (ds.blockchainInvest >= 100) {
                    revenueChange += 0.3;
                }

                var baseRevenue = 4.2;
                var projected = baseRevenue + revenueChange;
                if (d.revenueTarget && d.revenueTarget > projected) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('ambitious_target'), 'warning');
                }
                ds.expectedRevenue = projected;
            }

            ds.legalRisk = Math.max(0, Math.min(100, ds.legalRisk + riskChange));
            ds.revenueHistory.push(ds.expectedRevenue);
            ds.riskHistory.push(ds.legalRisk);

            // v1.1.0 FIX: this sim had NO numeric score — getPerformanceSummary returned
            // only a qualitative label, so results_utils.php::express_resolveDomainScore
            // resolved nothing (empty score). Persist a 0-100 score where it reads it.
            var _sc = this._computeScore(ds);
            ds.performance = { overallScore: _sc.total, grade: _sc.grade };
            ds.score = _sc.total;

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({currentPeriod: __eqilNext});
                self._renderProjects(ds);
            })(state.currentPeriod + 1), 500);

            return {
                period: period,
                budget: ds.budget,
                legalRisk: ds.legalRisk,
                activeProjects: ds.activeProjects,
                expectedRevenue: ds.expectedRevenue,
                overallScore: _sc.total
            };
        }

